sys_ws_operation.operation_script:
var CustomScriptIncludeAPI = Class.create();
CustomScriptIncludeAPI.prototype = Object.extendsObject(AbstractRestResource, {

    // Handle POST requests
    post: function() {
        var property = this.requestBody.data.sysparm_property; // Access data passed in the request body
        var suggestedValue = this.requestBody.data.sysparm_suggested_value; // Access suggested_value

        try {
            // Perform the server-side update of the property
            var gr = new GlideRecord('sys_properties'); // Assuming sys_properties is the correct table
            gr.get('name', property); // Replace with 'sys_id' if you're using sys_id
            if (gr.isValid()) {
                gr.setValue('value', suggestedValue);
                gr.update();
                return new sn_ws.Response().setStatus(200).setBody({ result: 'success' }); // Send success response
            } else {
                return new sn_ws.Response().setStatus(404).setBody({ result: 'error', message: 'Property not found' });
            }
        } catch (ex) {
            return new sn_ws.Response().setStatus(500).setBody({ result: 'error', message: ex.message });
        }
    }
});
